Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

(* [comment removed for export] *)
Ltac fold_b8 :=
  repeat match goal with |- context [bv_unsigned (Z_to_bv 8 ?z)] =>
    let v := eval vm_compute in (bv_unsigned (Z_to_bv 8 z)) in change (bv_unsigned (Z_to_bv 8 z)) with v end.
Ltac if_closed :=
  lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
    let v := eval vm_compute in c in first [constr_eq v true | constr_eq v false]; change c with v; cbv iota end.
Ltac istep := xstep; fold_b8; fold_closed_in_goal; try (first [if_closed | if_true | if_false]).
Ltac isteps_to p := repeat (tryif at_pc p then fail else istep).

Definition intscan_entry : Z := 0x202058.
(* [comment removed for export] *)
Definition INTSCAN_VAL : Z := 0x792a0 + 1.

Lemma val_ro : ro_bytes_b asegs (INTSCAN_VAL + 49) [Z_to_bv 8 1] = true /\ ro_bytes_b asegs (INTSCAN_VAL + 51) [Z_to_bv 8 3] = true.
Proof.
ltac2:(KReplay.run1 (kr_t_F_intscan ()) [] "p;3p;2p;4p;1p10000p4p7210p1000\p4p710p8g001:j33Tg001Tj2=Tg001nj4;Tg002Ij12Tg002nj10Tg003Sj11Tg0041j27Tg004Nj1:Tg004lj19Tg005Oj24Tg0065j18Tg006Uj36Tg0075j35Tg0081j2<Tg008LR0g008lR1;31R2P21=01R2P2C;g009LR2g00:DR3g00;ER4#2R5#0#0R6#0#2#1'7%04#0#0#:R7#9R8%14,47%88R43635=301%26#2#1,73%15,47=684552=301'<do"). Qed.

(* [comment removed for export] *)
Definition dval (ds : list Z) : Z := fold_left (fun x c => 10 * x + (c - 48)) ds 0.

Definition intscan_dot_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (f p : Z) (st : sfst) (ds : list Z) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (dval ds)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(f, f + 232); (bv_unsigned sp - 80, bv_unsigned sp)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' f (sfile (mkSF (p + Z.of_nat (length ds)) (sf_rend st) (sf_wend st) (sf_wpos st) (sf_wbase st) (sf_read st) (sf_buf st)
                                    (sf_bsz st) (sf_mode st) (sf_lock st) (sf_cookie st) (sf_shend st) (sf_shlim st) (sf_shcnt st))).

Theorem intscan_dot_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (f p : Z) (st : sfst) (ds : list Z) (lo : Z),
  a0 = Z_to_bv 64 f -> a1 = Z_to_bv 64 10 -> a2 = Z_to_bv 64 0 -> a3 = Z_to_bv 64 18446744073709551615 ->
  rw_cells asegs m f (sfile st) -> sf_ok st -> sf_rpos st = p -> sf_shlim st = Z_to_bv 64 0 ->
  (ds = [49] \/ ds = [51; 48]) -> bytes_at asegs m p (map (Z_to_bv 8) (ds ++ [46])) -> 0 < p -> p + Z.of_nat (length ds) + 1 <= sf_shend st ->
  p + 3 <= lo -> bv_unsigned sp <= f -> f + 232 <= 2^47 ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 80 -> mem_inv asegs m ->
  evt asegs (intscan_dot_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc f p st ds lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 intscan_entry) fc None m (seg_rom asegs)).
Proof.
