(* [comment removed for export] *)
Notation INTSCAN_DEPTH := 2480%Z (only parsing).

Section WithRIP.
Hypothesis RIP : rip_stmt.

Definition intscan_eof_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (f p : Z) (st : sfst) (ds : list Z) (kb : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (dval ds)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(f, f + 232); (bv_unsigned sp - INTSCAN_DEPTH, bv_unsigned sp)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' f (sfile (mkSF (p + 1) (p + 1) 0 0 0 (sf_read st) (sf_buf st) (sf_bsz st) SF_M1 (sf_lock st) (p + 1) (p + 1) SF_M1 (sf_shcnt st)))
    /\ bytes_at asegs m' (p + 1) kb.

Theorem intscan_eof_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (f p : Z) (st : sfst) (ds : list Z) (kb : list byte) (g : word) (lo : Z),
  a0 = Z_to_bv 64 f -> a1 = Z_to_bv 64 10 -> a2 = Z_to_bv 64 0 -> a3 = Z_to_bv 64 18446744073709551615 ->
  rw_cells asegs m f (sfile st) -> sf_ok st -> sf_rpos st = p -> sf_shend st = p + 1 -> sf_shlim st = Z_to_bv 64 0 -> sf_cookie st = p + 1 ->
  sf_wpos st = sf_wbase st -> (sf_mode st = Z_to_bv 64 0 \/ sf_mode st = SF_M1) -> sf_read st = string_read_entry ->
  sf_buf st + sf_bsz st < 2^47 -> sf_buf st <= p + 1 ->
  (ds = [56] \/ ds = [49]) -> bytes_at asegs m p (map (Z_to_bv 8) ds) -> 0 < p ->
  bytes_at asegs m (p + 1) kb -> find_byte 0 (firstn (Z.to_nat 257) kb) = Some 0%nat -> memchr_ok (p + 1) 0 257 kb ->
  p + 1 + Z.of_nat (length kb) <= lo ->
  chk_ok m (p + 1) 1 -> chk_ok m (bv_unsigned sp - 161) 1 -> m2s_cells m -> icells_mc m -> icells m -> ssp_cells m g ->
  bv_unsigned sp <= f -> f + 232 <= 2^47 ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - INTSCAN_DEPTH -> kHighShadowEnd + 8 <= lo -> mem_inv asegs m ->
  evt asegs (intscan_eof_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc f p st ds kb lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
